import { test, expect } from "@microsoft/tui-test";

// No API keys = wizard should appear
test.use({
  env: {
    LANGFUSE_PUBLIC_KEY: "",
    LANGFUSE_SECRET_KEY: "",
    // No OPENAI_API_KEY - triggers wizard
  },
});

test.describe("Setup Wizard", () => {
  test("shows disclaimer on first run", async ({ terminal }) => {
    // Wizard should show disclaimer panel
    await expect(
      terminal.getByText("Terms of Use", { timeout: 10000 })
    ).toBeVisible();

    // Disclaimer content should be visible
    await expect(
      terminal.getByText("NOTICE", { timeout: 5000 })
    ).toBeVisible();
  });

  test("accepts disclaimer and shows provider menu", async ({ terminal }) => {
    // Wait for disclaimer
    await expect(
      terminal.getByText("Terms of Use", { timeout: 10000 })
    ).toBeVisible();

    // Accept disclaimer
    terminal.write("ok");
    terminal.submit();

    // Provider menu should appear
    await expect(
      terminal.getByText("Provider Setup", { timeout: 5000 })
    ).toBeVisible();

    // Should show provider options
    await expect(
      terminal.getByText("Groq", { timeout: 3000 })
    ).toBeVisible();
  });

  test("can quit wizard with q", async ({ terminal }) => {
    // Wait for disclaimer
    await expect(
      terminal.getByText("Terms of Use", { timeout: 10000 })
    ).toBeVisible();

    // Accept disclaimer
    terminal.write("ok");
    terminal.submit();

    // Wait for provider menu
    await expect(
      terminal.getByText("Provider Setup", { timeout: 5000 })
    ).toBeVisible();

    // Quit wizard
    terminal.write("q");
    terminal.submit();

    // Should exit to main screen or exit app
    // Give time for transition
    await new Promise((r) => setTimeout(r, 2000));
  });

  test("can select provider and cancel", async ({ terminal }) => {
    // Wait for disclaimer
    await expect(
      terminal.getByText("Terms of Use", { timeout: 10000 })
    ).toBeVisible();

    // Accept disclaimer
    terminal.write("ok");
    terminal.submit();

    // Wait for provider menu
    await expect(
      terminal.getByText("Provider Setup", { timeout: 5000 })
    ).toBeVisible();

    // Select first provider (Groq)
    terminal.write("1");
    terminal.submit();

    // Should show configuration prompt
    await expect(
      terminal.getByText("Configuring", { timeout: 5000 })
    ).toBeVisible();

    // Cancel with q
    terminal.write("q");
    terminal.submit();

    // Should return to menu
    await expect(
      terminal.getByText("Provider Setup", { timeout: 5000 })
    ).toBeVisible();
  });
});
